    "让 AI 帮你动手，而不是只给建议": "Laissez l’IA faire le travail à votre place, pas seulement donner des conseils.",
    "Chapter 自带一个本机 MCP 服务。AI 能新建/修改卷章、改封面、改大纲、写 Markdown；删除与回档必须经过你确认。": "Chapter inclut un service MCP local. L'IA peut créer/modifier volumes et chapitres, changer la couverture, modifier le plan et écrire des fichiers Markdown ; toute suppression ou restauration doit être confirmée par vous.",
