    "三步接上（不用填代码）": "Connexion en trois étapes (sans code)",
    "打开支持 MCP 的 AI 客户端，选择「添加本地 MCP」，粘贴上方复制的配置。": "Ouvrez un client IA supportant MCP, sélectionnez « Ajouter un MCP local » et collez la configuration copiée ci-dessus.",
    "保持 Chapter 打开，并在书里点开要操作的那本小说。": "Gardez Chapter ouvert et ouvrez le roman à modifier.",
    "直接对 AI 说：帮我新建一卷、改第三章、写一份大纲。删除卷章和回档时，Chapter 会弹确认，只有你允许才执行。": "Dites directement à l'IA : « Crée un volume, modifie le chapitre 3, écris un plan. » Pour supprimer un volume/chapitre ou restaurer une version, Chapter demande votre confirmation et n'agit qu'après votre accord.",
    "新建小说": "Créer un nouveau roman",
