    "已回档，当前状态也自动存了一版": "Version restaurée. L'état actuel a aussi été enregistré automatiquement.",
    "存档线已创建": "Ligne de sauvegarde créée",
    "已切换存档线": "Ligne de sauvegarde changée",
    "正在检查 Git 环境…": "Vérification de l’environnement Git...",
    "先装一个 Git，之后全部点按钮": "D’abord, installez Git, puis cliquez sur tous les boutons",
    "Git 是一个免费的版本工具。你不需要敲命令，也不用手动建仓库；装好回来点一下，Chapter 会替你处理。": "Git est un outil de versions gratuit. Pas besoin de taper des commandes ni de créer un dépôt à la main : installez-le, revenez ici et cliquez, Chapter s'occupe du reste.",
    "未安装": "Non installé",
    "下载 Git for Windows": "Téléchargez Git pour Windows",
    "官方地址：git-scm.com。一路点「下一步」安装即可。": "Adresse officielle : git-scm.com. Il suffit de cliquer sur « Suivant » pour installer.",
    "打开下载页": "Ouvrir la page de téléchargement",
    "安装完成后": "Après la fin de l’installation",
    "回到这里点「重新检查」": "Retournez ici et cliquez sur « Revérifier »",
    "重新检查": "Revérifier",
    "Git 已就绪": "Git est prêt",
    "打开一本书之后，就能在这本书里开启版本管理。每本书是独立仓库，互不影响。": "Après l’ouverture d’un livre, la gestion des versions peut être activée à l’intérieur de ce livre. Chaque livre est un dépôt indépendant et ne s’influence pas mutuellement.",
    "已安装": "Installé",
    "先打开一本书，再回来这里。": "Ouvre d’abord un livre, puis reviens ici.",
    "把这本书变成可回档的工程": "Transformer ce livre en projet restaurable",
    "只影响当前这本书：会在工程目录里建一个本机 Git 仓库，不联网、不上传，也不会动别的书。": "Cela n’affecte que le livre en cours : il crée un dépôt Git natif dans le répertoire du projet, sans connexion internet, sans téléchargements ni autres livres.",
    "Git 已安装": "Git est installé",
    "开启版本管理": "Activer la gestion des versions",
    "第一次开启会自动存下当前版本，之后你想存档就点「存一版」。": "La première activation enregistre la version actuelle. Ensuite, cliquez sur « Enregistrer une version » quand vous voulez sauvegarder.",
    "版本管理已开启": "Gestion des versions activée",
    "写坏了就回来，不回不来就白写了": "Si vous avez tout cassé, revenez à une version précédente — sinon tout est perdu.",
    "每次存档都会留一个完整版本。回档不会删掉现在，系统会先把当前状态再存一版，然后才回到旧版本。": "Chaque sauvegarde conserve une version complète. La restauration ne supprime pas l'état actuel : il est d'abord sauvegardé, puis l'ancienne version est restaurée.",
    "有未存档改动": "Modifications non sauvegardées",
    "已存档": "Sauvegardé",
    "存一版": "Enregistrer une version",
    "可以写一句说明，也可以留空。": "Vous pouvez écrire une note ou la laisser vide.",
    "保存当前进度": "Enregistrer la progression",
    "例如：第三章重写前的版本": "Par exemple : la version avant la réécriture du chapitre 3",
    "版本时间线": "Chronologie des versions",
    "最近 60 个版本": "Les 60 dernières versions",
    "还没有版本。先点「保存当前进度」。": "Aucune version pour l'instant. Cliquez d'abord sur « Enregistrer la progression ».",
    "未命名存档": "Sauvegarde sans nom",
    "回到这一版？当前会先自动存一版。": "Revenir à cette version ? L'état actuel sera d'abord sauvegardé automatiquement.",
    "确认回档": "Confirmer la restauration",
    "回到这一版": "Revenir à cette version",
    "存档线（不是剧情分支）": "Ligne de sauvegarde (pas une branche de l'histoire)",
    "可选的进阶功能": "Fonction avancée facultative",
    "这里的「分支」是版本存档线，像同一本书的不同草稿线，不是故事里的剧情分支。普通写作只用一条线就够了。": "Ici, « branches » désignent la ligne d’archive de version, comme différentes lignes de brouillon dans un même livre, et non pas des branches d’intrigue au sein de l’histoire. Pour l’écriture ordinaire, une seule ligne suffit.",
