    "# 故事一句话\\n\\n> 主角想要什么，什么挡着他。\\n\\n## 第一幕 · 建置\\n- 日常世界\\n- 打破日常的事件\\n\\n## 第二幕 · 对抗\\n- 第一次尝试与失败\\n- 中点反转\\n- 最低谷\\n\\n## 第三幕 · 解决\\n- 最后的决断\\n- 余波\\n": "# Geschichte in einem Wort> Was will der Protagonist, was steht ihm im Weg. nn## Erste Akt · Bau – Alltagsweltn- Ereignisse, die den Alltag durchbrechennn## Akt Zwei · Konfrontationn- Erster Versuch und Misserfolgn- Umkehrung am Mittelpunktn## Akt Drei · Auflösungn- Endgültige Entscheidungn- Nachwirkungenn",
    "从这里开始写整本书的骨架……\\n\\n比如：\\n# 一句话故事\\n一个在长夜中找灯的人，最后发现灯一直在自己手里。\\n\\n## 主线\\n- 停电\\n- 离站\\n- 回城": "Von hier aus beginne du mit dem Schreiben des Rahmens des gesamten Buches...... zum Beispiel: n# Eine EinsatzgeschichtenEine Person, die in der langen Nacht nach einer Lampe sucht, nur um festzustellen, dass die Lampe immer in ihren eigenen Händen ist. nn## Hauptgeschichten- Stromausfalln- Verlassen der Stationn- Rückkehr in die Stadt.",
    "拖拽、滚轮或方向键切换；再点一次封面进入写作": "Ziehen, scrollen oder Pfeiltasten wechseln; Tippen Sie erneut auf den Cover, um mit dem Schreiben zu beginnen",
