    "工程会落在本机书库目录里，一个 .chapter 文件夹就是一本。": "Das Projekt wird im lokalen Bibliotheksverzeichnis platziert, und ein .chapter-Ordner ist ein Buch.",
    "例如：长夜将尽": "Zum Beispiel: Die lange Nacht geht zu Ende",
    "笔名，可留空": "Pseudonym, leer lassen",
    "给你一卷一章的空架子，立刻能写。": "Wenn du ein leeres Regal mit einem Band oder einem Kapitel hast, kannst du sofort schreiben.",
    "按「建置 / 对抗 / 解决」铺好三卷九章，章名可随时改。": "Ordnen Sie drei Bände und neun Kapitel entsprechend \"Establishment / Konfrontation / Lösung\" an, und die Kapiteltitel können jederzeit geändert werden.",
    "确定": "Bestätigen",
    "带目录、章节分页，封面会一起打包；阅读器里排版最完整。": "Enthält Inhaltsverzeichnis und Kapitelseiten, wobei das Cover zusammengefasst ist; Das vollständigste Layout im Leser.",
    "按卷、章分好层级的 .md，方便继续用别的工具处理。": "Organisieren Sie hierarchische .md-Dateien nach Volume und Kapitel, um die Nutzung anderer Werkzeuge für die Verarbeitung zu erleichtern.",
    "纯文本 TXT": "Klartext-TXT",
    "去格式的干净正文，投稿、备份、发给别人看都省事。": "Entfernen Sie das Clean Body-Format; Einreichen, Sichern und Teilen mit anderen sind alles praktisch.",
    "导出这本书": "Dieses Buch exportieren",
