    "每次打开书与手动存版都会留一份；最多保留最近 20 个。恢复前会自动备份当前状态。": "Jedes Mal, wenn ein Buch geöffnet oder manuell gespeichert wird, wird eine Kopie aufbewahrt; Bis zu den neuesten 20 werden aufbewahrt. Der aktuelle Zustand wird vor der Wiederherstellung automatisch gesichert.",
