    "自定义封面不画书脊，只用这个颜色做侧面。": "Das maßgefertigte Cover lackiert den Buchrücken nicht, nur diese Farbe wird für die Seite verwendet.",
    "默认封面自带书脊；换成自定义封面后，可以单独选书脊颜色。": "Standardmäßig kommt das Cover mit einem Buchrücken; Nach dem Wechsel zu einem individuellen Cover können Sie die Buchrückenfarbe separat auswählen.",
