    "分光": "Spot",
    "常驻：丝带一直亮着。流动：光从左上扫到右下。分光：鼠标照到哪里，丝带才在哪里显现。": "Permanent: Das Ribbon bleibt kontinuierlich beleuchtet. Flow: Das Licht schweigt von der oberen linken Ecke nach unten rechts. Geteiltes Licht: Das Ribbon erscheint nur dort, wo die Maus ihn trifft.",
    "章节识别": "Kapitelidentifikation",
    "章标记词": "Kapitelmarkierungsbegriffe",
    "卷标记词": "Volume-Tag-Wort",
    "特殊标题": "Sondertitel",
    "用顿号分隔，例如「章、回、节」。导入时按这些词识别章节；作者会从正文开头的「作者：」自动填写。": "Verwenden Sie Kommazeichen, um sie zu trennen, wie zum Beispiel \"Kapitel, Kapitel, Kapitel\" oder \"Abschnitt\". Beim Importieren identifizieren Sie Kapitel anhand dieser Wörter; Autoren füllen automatisch das Wort \"Autor:\" am Anfang des Haupttextes aus.",
    "保存识别词": "Speichern Sie die Identifikation",
    "（读取中）": "(Lesen)",
    "关于 Chapter": "Über Chapter",
    "小方工作室 · 长篇小说写作工作台": "Xiaofang Studio · Schreibtisch für Romane",
    "把卷、章、场景、人物设定、字数目标和 EPUB 导出收在一张书桌上。本地优先，零账号，正文只留在这台电脑。": "Exportieren Sie Bände, Kapitel, Szenen, Charaktereinstellungen, Wortanzahlziele und EPUBs alles auf einem Schreibtisch. Erst lokal, keine Konten, Haupttext nur auf diesem Computer.",
