    "本地优先 · 零账号 · 零联网 · 正文永远只在这台电脑上。": "Local First · Zero Account · Zero Internet · Der Haupttext befindet sich immer nur auf diesem Computer.",
    "简体中文": "Chinesisch vereinfacht",
    "设置栏目": "Bereiche",
    "个性化": "Personalisierung",
    "界面长什么样、动效多快、用什么语言，都在这里。": "Wie die Benutzeroberfläche aussieht, wie schnell die Animationen sind, welche Sprache man verwenden soll – all das ist hier.",
    "进入 Chapter 时先看到哪种首页": "Startseite beim Öffnen von Chapter",
    "夕阳是亮色纸，夜幕是暗色纸": "Der Sonnenuntergang ist helles Papier, die Nacht ist dunkles Papier",
    "背景、按钮和丝带会一起变": "Hintergrund, Schaltflächen und Menüband ändern sich gemeinsam",
    "常驻一直亮；流动从左扫到右；分光跟鼠标走": "Dauerhaft: immer an; Fluss: von links nach rechts; Spot: folgt der Maus.",
    "关掉后最省电、最跟手": "Aus: am sparsamsten und direktesten.",
    "只在这里切换一次，不再有第二处": "Hier nur einmal wechseln, kein zweiter Platz",
    "写作与纸面": "Schreiben & Papier",
    "纸、背景、目标、章节识别词和书库位置。": "Papier, Hintergrund, Ziel, Kapitelerkennungswörter und Standorte der Bibliothek.",
    "正文纸面始终干净，背景只铺在界面底层": "Der Haupttext ist auf dem Papier immer sauber, der Hintergrund liegt nur unten in der Benutzeroberfläche",
    "保存目标": "Das Ziel speichern",
    "导入书稿时按这些词分章。用顿号分隔。": "Beim Import des Manuskripts teilen Sie die Kapitel nach diesen Wörtern ein. Verwenden Sie Aufzählungszeichen, um sie voneinander zu trennen.",
    "添加场景": "Szenen hinzufügen",
    "添加一章": "Ein Kapitel hinzufügen",
    "展开": "Erweitern",
    "收起": "Verstauen",
    "本章更多": "Mehr in diesem Kapitel",
    "小方工作室 · 小说写作工作台": "Xiaofang Studio · Schreibtisch für Romane",
    "一章一章，": "Kapitel für Kapitel,",
    "写下去。": "Schreib weiter.",
    "卷、章、场景，人物与设定，字数目标与专注模式——写长篇小说要用的东西，都收在这一张书桌上。写完，直接导出 EPUB。": "Bände, Kapitel, Szenen, Charaktere und Schauplätze, Ziele zur Wortanzahl und Fokusmodi – alles, was zum Schreiben eines Romans nötig ist, wird auf diesem Schreibtisch gespeichert. Nach dem Schreiben direkt an EPUB exportieren.",
    "先想一个能一句话讲完的故事，再拆成卷与章。": "Zuerst entwickle dir eine Geschichte, die in einem Satz erzählt werden kann, und teile sie dann in Bände und Kapitel auf.",
    "别急着写漂亮句子，先把今天这一章写完。": "Beeilen Sie sich nicht, schöne Sätze zu schreiben – beenden Sie zuerst das heutige Kapitel.",
    "人物设定先立主角与对手，其余边写边补。": "Die Charaktereinstellungen beginnen mit Protagonisten und Antagonisten und füllen den Rest beim Schreiben aus.",
    "新建后会得到「第一卷 / 第一章」，直接就能写。": "Nachdem du einen neuen erstellt hast, erhältst du \"Band 1 / Kapitel 1\", mit dem du sofort beginnen kannst zu schreiben.",
    "晨光": "Morgenlicht",
    "晴": "Frei",
