    "还没落笔。哪怕只写一段，也比空白好。": "Er hatte noch nicht einmal angefangen zu schreiben. Selbst wenn er nur einen Absatz schrieb, war das besser als eine leere Leere.",
    "操作失败": "Operation fehlgeschlagen",
