    "让 AI 帮你动手，而不是只给建议": "Lass die KI für dich arbeiten, nicht nur Ratschläge geben.",
    "Chapter 自带一个本机 MCP 服务。AI 能新建/修改卷章、改封面、改大纲、写 Markdown；删除与回档必须经过你确认。": "Chapter enthält einen lokalen MCP-Dienst. Die KI kann Bände und Kapitel erstellen/ändern, Cover und Gliederung bearbeiten und Markdown schreiben; Löschen und Wiederherstellen müssen Sie bestätigen.",
