    "打开支持 MCP 的 AI 客户端，选择「添加本地 MCP」，粘贴上方复制的配置。": "Öffnen Sie einen KI-Client, der MCP unterstützt, wählen Sie \"Lokalen MCP hinzufügen\" und fügen Sie die obige kopierte Konfiguration ein.",
    "保持 Chapter 打开，并在书里点开要操作的那本小说。": "Lass Chapter geöffnet und öffne den Roman, den du bearbeiten willst.",
    "直接对 AI 说：帮我新建一卷、改第三章、写一份大纲。删除卷章和回档时，Chapter 会弹确认，只有你允许才执行。": "Sage der KI direkt: „Erstelle einen Band, ändere Kapitel 3, schreibe eine Gliederung.“ Beim Löschen von Bänden/Kapiteln oder Wiederherstellen fragt Chapter nach Ihrer Bestätigung.",
