    "先装一个 Git，之后全部点按钮": "Zuerst Git installieren und dann alle Schaltflächen anklicken",
    "Git 是一个免费的版本工具。你不需要敲命令，也不用手动建仓库；装好回来点一下，Chapter 会替你处理。": "Git ist ein kostenloses Versionswerkzeug. Sie müssen keine Befehle eingeben und kein Repository von Hand anlegen: installieren, hierher zurückkehren, klicken – Chapter erledigt den Rest.",
    "未安装": "Nicht installiert",
    "下载 Git for Windows": "Git für Windows herunterladen",
    "官方地址：git-scm.com。一路点「下一步」安装即可。": "Offizielle Adresse: git-scm.com. Klicken Sie einfach auf \"Weiter\", um zu installieren.",
    "打开下载页": "Öffnen Sie die Download-Seite",
    "安装完成后": "Nach Abschluss der Installation",
    "回到这里点「重新检查」": "Gehen Sie hierher zurück und klicken Sie auf \"Noch einmal überprüfen\".",
    "重新检查": "Erneut überprüfen",
    "Git 已就绪": "Git ist bereit",
    "打开一本书之后，就能在这本书里开启版本管理。每本书是独立仓库，互不影响。": "Nach dem Öffnen eines Buches kann die Versionsverwaltung innerhalb dieses Buches aktiviert werden. Jedes Buch ist ein eigenständiges Repository und beeinflusst sich nicht gegenseitig.",
    "已安装": "Installiert",
    "先打开一本书，再回来这里。": "Öffne zuerst ein Buch, komm dann zurück.",
    "把这本书变成可回档的工程": "Dieses Buch in ein wiederherstellbares Projekt verwandeln",
    "只影响当前这本书：会在工程目录里建一个本机 Git 仓库，不联网、不上传，也不会动别的书。": "Es betrifft nur das aktuelle Buch: Es erstellt ein natives Git-Repository im Projektverzeichnis, ohne Internetverbindung, Uploads oder andere Bücher.",
    "Git 已安装": "Git ist installiert",
    "开启版本管理": "Versionsverwaltung aktivieren",
    "第一次开启会自动存下当前版本，之后你想存档就点「存一版」。": "Beim ersten Aktivieren wird die aktuelle Version automatisch gespeichert. Danach bei Bedarf „Version speichern“ klicken.",
    "版本管理已开启": "Versionsverwaltung aktiv",
    "写坏了就回来，不回不来就白写了": "Wenn etwas schiefgeht, einfach zurückkehren – sonst ist die Arbeit verloren.",
    "每次存档都会留一个完整版本。回档不会删掉现在，系统会先把当前状态再存一版，然后才回到旧版本。": "Jede Speicherung behält eine vollständige Version. Beim Wiederherstellen geht der aktuelle Stand nicht verloren: Er wird zuerst gesichert, dann wird die alte Version geladen.",
    "有未存档改动": "Ungespeicherte Änderungen",
