    "还没有版本。先点「保存当前进度」。": "Noch keine Version. Klicken Sie zuerst auf „Fortschritt speichern“.",
    "未命名存档": "Unbenannte Sicherung",
    "回到这一版？当前会先自动存一版。": "Zu dieser Version zurückkehren? Der aktuelle Stand wird zuerst automatisch gespeichert.",
