    "可选的进阶功能": "Optionale erweiterte Funktion",
    "这里的「分支」是版本存档线，像同一本书的不同草稿线，不是故事里的剧情分支。普通写作只用一条线就够了。": "Hier beziehen sich \"Äste\" auf die Versionsarchivzeile, ähnlich wie verschiedene Entwürfe im selben Buch, nicht auf Handlungszweige innerhalb der Geschichte. Für gewöhnliches Schreiben reicht nur eine Zeile aus.",
