    "《{title}》会从目录里移除。稿件文件会改名成 .md.deleted 留在工程目录，后悔了还能捞回来。": "„{title}“ wird aus dem Inhaltsverzeichnis entfernt. Die Manuskriptdatei wird in .md.deleted umbenannt und im Projektordner behalten, damit du sie wiederherstellen kannst.",
