    "工程会落在本机书库目录里，一个 .chapter 文件夹就是一本。": "El proyecto se colocará en el directorio de la biblioteca local, y una carpeta .chapter es un libro.",
    "例如：长夜将尽": "Por ejemplo: La larga noche está terminando",
    "笔名，可留空": "Seudónimo, déjalo en blanco",
    "给你一卷一章的空架子，立刻能写。": "Si tienes una estantería vacía con un volumen o un capítulo, puedes escribir inmediatamente.",
    "按「建置 / 对抗 / 解决」铺好三卷九章，章名可随时改。": "Organiza tres volúmenes y nueve capítulos según \"Establecimiento / Confrontación / Resolución\", y los títulos de los capítulos pueden cambiarse en cualquier momento.",
    "确定": "Confirma",
    "带目录、章节分页，封面会一起打包；阅读器里排版最完整。": "Incluye índice de contenidos y páginas de capítulo, con la portada empaquetada junta; El diseño más completo en el lector.",
    "按卷、章分好层级的 .md，方便继续用别的工具处理。": "Organiza archivos .md jerárquicos por volumen y capítulo, facilitando el uso de otras herramientas para el procesamiento.",
    "纯文本 TXT": "TXT de texto plano",
    "去格式的干净正文，投稿、备份、发给别人看都省事。": "Elimina el formato de cuerpo limpio; enviar, hacer copias de seguridad y compartir con otros es todo muy cómodo.",
    "导出这本书": "Exporta este libro",
    "全部在本机完成，不经过任何服务器。": "Todo se hace localmente, sin pasar por ningún servidor.",
    "含封面": "Incluye cobertura",
    "无封面": "Sin cobertura",
    "每次打开书与手动存版都会留一份；最多保留最近 20 个。恢复前会自动备份当前状态。": "Cada vez que se abre o guarda manualmente un libro, se conserva una copia; Se conservan hasta los 20 más recientes. El estado actual se guarda automáticamente antes de la restauración.",
    " · 最新": "· Últimas novidades",
    "书脊颜色": "El color del lomo",
    "自定义颜色": "Colores personalizados",
    "自定义封面不画书脊，只用这个颜色做侧面。": "La portada personalizada no pinta el lomo, solo se usa este color para el lateral.",
    "默认封面自带书脊；换成自定义封面后，可以单独选书脊颜色。": "Por defecto, la portada viene con un lomo; Tras cambiar a una portada personalizada, puedes elegir el color del lomo por separado.",
    "主题色": "Color del tema",
    "背景光效": "Efecto de luz",
