    "分光": "Foco",
    "常驻：丝带一直亮着。流动：光从左上扫到右下。分光：鼠标照到哪里，丝带才在哪里显现。": "Permanente: La cinta permanece iluminada de forma continua. Flujo: La luz se desplaza desde la parte superior izquierda hacia la inferior derecha. Luz dividida: La cinta aparece solo donde el ratón golpea.",
    "章节识别": "Identificación de capítulos",
    "章标记词": "Términos de los marcadores de capítulo",
    "卷标记词": "Palabra de etiqueta de volumen",
    "特殊标题": "Título especial",
    "用顿号分隔，例如「章、回、节」。导入时按这些词识别章节；作者会从正文开头的「作者：」自动填写。": "Utiliza comas para separarlos, como \"capítulo, capítulo, capítulo\" o \"sección\". Al importar, identifica los capítulos por estas palabras; Los autores rellenarán automáticamente \"autor:\" al principio del texto principal.",
    "保存识别词": "Guardar el identificador",
    "（读取中）": "(Leyendo)",
    "关于 Chapter": "Acerca de Chapter",
    "小方工作室 · 长篇小说写作工作台": "Xiaofang Studio · Banco de trabajo para escribir novelas",
    "把卷、章、场景、人物设定、字数目标和 EPUB 导出收在一张书桌上。本地优先，零账号，正文只留在这台电脑。": "Exporta volúmenes, capítulos, escenas, configuraciones de personajes, objetivos de conteo de palabras y EPUBs, todo en una sola mesa. Primero local, cero cuentas, solo texto principal en este ordenador.",
