    "设置栏目": "Secciones",
    "个性化": "Personalización",
    "界面长什么样、动效多快、用什么语言，都在这里。": "Cómo es la interfaz, la velocidad de las animaciones, qué lenguaje usar... todo está aquí.",
    "进入 Chapter 时先看到哪种首页": "Página de inicio al abrir Chapter",
    "夕阳是亮色纸，夜幕是暗色纸": "El atardecer es papel brillante, la noche es papel oscuro",
    "背景、按钮和丝带会一起变": "El fondo, los botones y la cinta de opciones cambiarán juntos",
    "常驻一直亮；流动从左扫到右；分光跟鼠标走": "Fijo: siempre encendido; Flujo: de izquierda a derecha; Foco: sigue el ratón.",
    "关掉后最省电、最跟手": "Desactivadas: lo más eficiente y directo.",
    "只在这里切换一次，不再有第二处": "Solo cambie aquí una vez, no hay segundo puesto",
    "写作与纸面": "Escritura y papel",
    "纸、背景、目标、章节识别词和书库位置。": "Papel, fondo, objetivo, palabras de reconocimiento de capítulos y ubicaciones de bibliotecas.",
    "正文纸面始终干净，背景只铺在界面底层": "El texto principal siempre está limpio en papel, con el fondo solo situado en la parte inferior de la interfaz",
    "保存目标": "Guardar el objetivo",
    "导入书稿时按这些词分章。用顿号分隔。": "Al importar el manuscrito, divide los capítulos según estas palabras. Utiliza marcas de enumeración para separarlos.",
    "添加场景": "Añadir escenas",
    "添加一章": "Añadir un capítulo",
    "展开": "Expandir",
    "收起": "Guarda",
    "本章更多": "Más en este capítulo",
    "小方工作室 · 小说写作工作台": "Xiaofang Studio · Banco de trabajo para escribir novelas",
    "一章一章，": "Capítulo por capítulo,",
    "写下去。": "Sigue escribiendo.",
    "卷、章、场景，人物与设定，字数目标与专注模式——写长篇小说要用的东西，都收在这一张书桌上。写完，直接导出 EPUB。": "Volúmenes, capítulos, escenas, personajes y escenarios, objetivos de conteo de palabras y modos de enfoque: todo lo necesario para escribir una novela se almacena en este escritorio. Después de escribir, exporta directamente a EPUB.",
    "先想一个能一句话讲完的故事，再拆成卷与章。": "Primero, crea una historia que pueda contarse en una sola frase y luego divídela en volúmenes y capítulos.",
    "别急着写漂亮句子，先把今天这一章写完。": "No te apresures a escribir frases hermosas—termina primero el capítulo de hoy.",
    "人物设定先立主角与对手，其余边写边补。": "Los escenarios de personaje empiezan con el protagonista y los antagonistas, y luego completan el resto conforme escribes.",
    "新建后会得到「第一卷 / 第一章」，直接就能写。": "Después de crear uno nuevo, recibirás \"Volumen 1 / Capítulo 1\", que podrás empezar a escribir inmediatamente.",
