    "让 AI 帮你动手，而不是只给建议": "Deja que la IA haga el trabajo por ti, no solo te aconseje.",
    "Chapter 自带一个本机 MCP 服务。AI 能新建/修改卷章、改封面、改大纲、写 Markdown；删除与回档必须经过你确认。": "Chapter incluye un servicio MCP local. La IA puede crear/editar volúmenes y capítulos, cambiar la portada, modificar el esquema y escribir Markdown; eliminar o restaurar siempre requiere tu confirmación.",
