    "打开支持 MCP 的 AI 客户端，选择「添加本地 MCP」，粘贴上方复制的配置。": "Abre un cliente de IA que soporte MCP, selecciona \"Añadir MCP local\" y pega la configuración copiada arriba.",
    "保持 Chapter 打开，并在书里点开要操作的那本小说。": "Mantén Chapter abierto y abre el libro que quieres editar.",
    "直接对 AI 说：帮我新建一卷、改第三章、写一份大纲。删除卷章和回档时，Chapter 会弹确认，只有你允许才执行。": "Dile directamente a la IA: «Crea un volumen, cambia el capítulo 3, escribe un esquema». Al eliminar volúmenes/capítulos o restaurar, Chapter pedirá tu confirmación.",
