    "先装一个 Git，之后全部点按钮": "Primero, instala Git y luego haz clic en todos los botones",
    "Git 是一个免费的版本工具。你不需要敲命令，也不用手动建仓库；装好回来点一下，Chapter 会替你处理。": "Git es una herramienta gratuita de versiones. No necesitas escribir comandos ni crear un repositorio a mano: instálalo, vuelve aquí y pulsa; Chapter se encarga del resto.",
    "未安装": "No instalado",
    "下载 Git for Windows": "Descarga Git para Windows",
    "官方地址：git-scm.com。一路点「下一步」安装即可。": "Dirección oficial: git-scm.com. Solo tienes que hacer clic en \"Siguiente\" para instalar.",
    "打开下载页": "Abrir la página de descarga",
    "安装完成后": "Una vez completada la instalación",
    "回到这里点「重新检查」": "Vuelve aquí y haz clic en \"Recheck\"",
    "重新检查": "Volver a comprobar",
    "Git 已就绪": "Git está listo",
    "打开一本书之后，就能在这本书里开启版本管理。每本书是独立仓库，互不影响。": "Tras abrir un libro, la gestión de versiones puede activarse dentro de ese libro. Cada libro es un repositorio independiente y no afecta a los demás.",
    "已安装": "Instalado",
    "先打开一本书，再回来这里。": "Abre un libro primero y luego vuelve aquí.",
    "把这本书变成可回档的工程": "Convertir este libro en un proyecto restaurable",
    "只影响当前这本书：会在工程目录里建一个本机 Git 仓库，不联网、不上传，也不会动别的书。": "Solo afecta al libro actual: crea un repositorio Git nativo en el directorio del proyecto, sin conexión a internet, sin cargas ni otros libros.",
    "Git 已安装": "Git está instalado",
    "开启版本管理": "Activar gestión de versiones",
    "第一次开启会自动存下当前版本，之后你想存档就点「存一版」。": "Al activarla por primera vez se guarda la versión actual. Después, pulsa «Guardar versión» cuando quieras guardar.",
    "版本管理已开启": "Gestión de versiones activada",
    "写坏了就回来，不回不来就白写了": "Si algo se estropea, vuelve a una versión anterior; si no, todo se pierde.",
    "每次存档都会留一个完整版本。回档不会删掉现在，系统会先把当前状态再存一版，然后才回到旧版本。": "Cada guardado conserva una versión completa. Restaurar no borra el estado actual: primero se guarda y luego se recupera la versión anterior.",
