    "这里的「分支」是版本存档线，像同一本书的不同草稿线，不是故事里的剧情分支。普通写作只用一条线就够了。": "Aquí, 'ramas' se refieren a la línea de archivo de versiones, como diferentes líneas de borrador en el mismo libro, no a ramas de trama dentro de la historia. Para la escritura ordinaria, basta con una sola línea.",
