    "小方工作室 · 长篇小说写作工作台": "Xiaofang Studio · Bancada de trabalho para escrita de romances",
    "把卷、章、场景、人物设定、字数目标和 EPUB 导出收在一张书桌上。本地优先，零账号，正文只留在这台电脑。": "Exporte volumes, capítulos, cenas, configurações de caracteres, metas de contagem de palavras e EPUBs, tudo em uma única mesa. Local primeiro, zero contas, apenas texto principal neste computador.",
