    "界面长什么样、动效多快、用什么语言，都在这里。": "Como é a interface, quão rápidas são as animações, qual idioma usar—tudo está aqui.",
    "进入 Chapter 时先看到哪种首页": "Página inicial ao abrir o Chapter",
