    "一章一章，": "Capítulo por capítulo,",
    "写下去。": "Continue escrevendo.",
    "卷、章、场景，人物与设定，字数目标与专注模式——写长篇小说要用的东西，都收在这一张书桌上。写完，直接导出 EPUB。": "Volumes, capítulos, cenas, personagens e cenários, contagem de palavras, metas e modos de foco—tudo o que é necessário para escrever um romance está armazenado nesta mesa. Após escrever, exporte diretamente para o EPUB.",
    "先想一个能一句话讲完的故事，再拆成卷与章。": "Primeiro, crie uma história que possa ser contada em uma frase só, depois divida-a em volumes e capítulos.",
