    "人物设定先立主角与对手，其余边写边补。": "As configurações dos personagens começam com o protagonista e os antagonistas, depois preenchem o resto conforme você escreve.",
    "新建后会得到「第一卷 / 第一章」，直接就能写。": "Depois de criar um novo, você receberá o \"Volume 1 / Capítulo 1\", que poderá começar a escrever imediatamente.",
