    "Chapter 自带一个本机 MCP 服务。AI 能新建/修改卷章、改封面、改大纲、写 Markdown；删除与回档必须经过你确认。": "O Chapter inclui um serviço MCP local. A IA pode criar/editar volumes e capítulos, alterar a capa, modificar o esboço e escrever Markdown; eliminar ou restaurar exige sempre a sua confirmação.",
