    "打开支持 MCP 的 AI 客户端，选择「添加本地 MCP」，粘贴上方复制的配置。": "Abra um cliente de IA que suporte MCP, selecione \"Adicionar MCP Local\" e cole a configuração copiada acima.",
    "保持 Chapter 打开，并在书里点开要操作的那本小说。": "Mantenha o Chapter aberto e abra o livro que quer editar.",
