    "先装一个 Git，之后全部点按钮": "Primeiro, instale o Git e depois clique em todos os botões",
    "Git 是一个免费的版本工具。你不需要敲命令，也不用手动建仓库；装好回来点一下，Chapter 会替你处理。": "Git é uma ferramenta gratuita de versões. Não precisa de escrever comandos nem criar um repositório à mão: instale, volte aqui e clique; o Chapter trata do resto.",
    "未安装": "Não instalado",
    "下载 Git for Windows": "Baixe o Git para Windows",
    "官方地址：git-scm.com。一路点「下一步」安装即可。": "Endereço oficial: git-scm.com. Basta clicar em \"Avançar\" para instalar.",
    "打开下载页": "Abra a página de download",
    "安装完成后": "Após a conclusão da instalação",
