    "重新检查": "Recheck",
    "Git 已就绪": "Git está pronto",
    "打开一本书之后，就能在这本书里开启版本管理。每本书是独立仓库，互不影响。": "Após abrir um livro, o gerenciamento de versões pode ser habilitado dentro desse livro. Cada livro é um repositório independente e não afeta uns aos outros.",
    "已安装": "Instalado",
    "先打开一本书，再回来这里。": "Abra um livro primeiro, depois volte aqui.",
    "把这本书变成可回档的工程": "Transformar este livro em um projeto restaurável",
    "只影响当前这本书：会在工程目录里建一个本机 Git 仓库，不联网、不上传，也不会动别的书。": "Ele afeta apenas o livro atual: cria um repositório Git nativo no diretório do projeto, sem conexão com a internet, uploads ou outros livros.",
    "Git 已安装": "Git está instalado",
    "开启版本管理": "Ativar gerenciamento de versões",
    "第一次开启会自动存下当前版本，之后你想存档就点「存一版」。": "Na primeira ativação, a versão atual é salva. Depois, clique em «Salvar versão» quando quiser salvar.",
    "版本管理已开启": "Gerenciamento de versões ativado",
    "写坏了就回来，不回不来就白写了": "Se algo der errado, volte a uma versão anterior — senão tudo se perde.",
    "每次存档都会留一个完整版本。回档不会删掉现在，系统会先把当前状态再存一版，然后才回到旧版本。": "Cada salvamento mantém uma versão completa. Restaurar não apaga o estado atual: ele é salvo primeiro e depois a versão antiga é restaurada.",
