    "保持 Chapter 打开，并在书里点开要操作的那本小说。": "Держите Chapter открытым и откройте книгу, которую хотите редактировать.",
    "直接对 AI 说：帮我新建一卷、改第三章、写一份大纲。删除卷章和回档时，Chapter 会弹确认，只有你允许才执行。": "Скажите ИИ прямо: «Создай том, измени главу 3, напиши план». При удалении томов и глав или восстановлении Chapter спросит подтверждение.",
