    "Git 是一个免费的版本工具。你不需要敲命令，也不用手动建仓库；装好回来点一下，Chapter 会替你处理。": "Git — бесплатный инструмент версий. Вводить команды и создавать репозиторий вручную не нужно: установите, вернитесь сюда и нажмите — Chapter всё сделает.",
