    "只影响当前这本书：会在工程目录里建一个本机 Git 仓库，不联网、不上传，也不会动别的书。": "Это влияет только на текущую книгу: создаёт родной Git-репозиторий в каталоге проектов без подключения к интернету, загрузок или других книг.",
    "Git 已安装": "Git установлен",
