    "自定义封面不画书脊，只用这个颜色做侧面。": "الغطاء المخصص لا يطلي العمود الفقري، فقط هذا اللون يستخدم للجانب.",
    "默认封面自带书脊；换成自定义封面后，可以单独选书脊颜色。": "بشكل افتراضي، يأتي الغلاف مع عمود فقري؛ بعد التبديل إلى غلاف مخصص، يمكنك اختيار لون العمود الفقري بشكل منفصل.",
