    "特殊标题": "العنوان الخاص",
    "用顿号分隔，例如「章、回、节」。导入时按这些词识别章节；作者会从正文开头的「作者：」自动填写。": "استخدم علامات فواصل لفصلها، مثل \"فصل، فصل، فصل\" أو \"قسم\". عند الاستيراد، حدد الفصول بهذه الكلمات؛ سيقوم المؤلفون تلقائيا بملء \"المؤلف:\" في بداية النص الرئيسي.",
    "保存识别词": "حفظ المعرف",
    "（读取中）": "(يقرأ)",
