    "把卷、章、场景、人物设定、字数目标和 EPUB 导出收在一张书桌上。本地优先，零账号，正文只留在这台电脑。": "تصدير المجلدات، الفصول، المشاهد، إعدادات الشخصيات، أهداف عدد الكلمات، وملفات EPUB كلها على مكتب واحد. محلي أولا، صفر حسابات، النص الرئيسي فقط على هذا الكمبيوتر.",
