    "正文纸面始终干净，背景只铺在界面底层": "النص الرئيسي دائما نظيف على الورق، مع وضع الخلفية فقط في أسفل الواجهة",
    "保存目标": "حفظ الهدف",
    "导入书稿时按这些词分章。用顿号分隔。": "عند استيراد المخطوطة، قسم الفصول حسب هذه الكلمات. استخدم علامات التعداد لفصلها.",
