    "先想一个能一句话讲完的故事，再拆成卷与章。": "أولا، ابتكر قصة يمكن سردها في جملة واحدة، ثم قسمها إلى مجلدات وفصول.",
    "别急着写漂亮句子，先把今天这一章写完。": "لا تتسرع في كتابة جمل جميلة—أنه فصل اليوم أولا.",
    "人物设定先立主角与对手，其余边写边补。": "إعدادات الشخصيات تبدأ بالبطل والخصوم، ثم تكمل الباقي أثناء الكتابة.",
    "新建后会得到「第一卷 / 第一章」，直接就能写。": "بعد إنشاء كتاب جديد، ستتلقى \"المجلد 1 / الفصل 1\"، والذي يمكنك البدء في كتابته فورا.",
