    "今天的对话，删掉所有‘你知道的’。": "في حديث اليوم، احذف كل كلمة 'أنت تعرف'.",
    "让一个人物改变主意，但不承认。": "اجعل الشخصية تغير رأيها، لكن لا تعترف بذلك.",
