    "把最热闹的场面写成一个近景。": "حول المشاهد الحيوية إلى لقطة مقربة.",
    "让一个人物说‘没事’，然后做点什么。": "اجعل شخصية تقول 'لا بأس'، ثم افعل شيئا.",
    "今天的章节结尾，留一扇没关的门。": "في نهاية فصل اليوم، اترك بابا مفتوحا وغير مغلق.",
    "让读者担心一个还没出场的人。": "يجعل القراء يقلقون بشأن شخص لم يظهر بعد.",
    "给反派一个合理的早晨。": "أعط الشرير صباحا معقولا.",
    "让人物把话说一半。": "دع الشخصية تقول نصف الجملة.",
    "故事里的光，最好来自具体的地方。": "يفضل أن يأتي الضوء في القصة من مكان محدد.",
